/**
 * travel.js — the map, the pins and the memoirs
 *
 * URL:    travel.html                the map and the lists
 *         travel.html?trip=<slug>    a trip memoir open
 *         travel.html?place=<slug>   a standing place open
 * Reads:  /trips/index.json          generated by tools/build_travel.py
 *         /trips/<slug>/index.md     a trip memoir
 *         /places/<slug>/index.md    a standing place
 *         /assets/world.svg          generated by tools/build_worldmap.py
 *
 * Dependency (loaded before this script): marked.js v12 (window.marked)
 */

/* ═══════════════════════════════════════════════════════════════════════
   PROJECTION
   Equirectangular, and it must match tools/build_worldmap.py exactly or the
   pins drift away from the coastlines.
   ═══════════════════════════════════════════════════════════════════════ */
var MAP_WIDTH = 1000;
var MAP_HEIGHT = MAP_WIDTH / 2;

function projectX(lon) { return (lon + 180) * (MAP_WIDTH / 360); }
function projectY(lat) { return (90 - lat) * (MAP_HEIGHT / 180); }

var SVG_NS = 'http://www.w3.org/2000/svg';

/* Pins are drawn at unit size and scaled by the inverse of the zoom, so they
   stay the same size on screen however far in you go. */
var PIN_R = 3.2;
var HIT_R = 13;          /* the invisible disc that actually takes the clicks */
/* Recommendations are venue-scale: two restaurants on the same road sit ~200m
   apart, which is 0.005 of a viewBox unit. At 40x the whole view was still
   1000km across and such pins landed on the same pixel, leaving one of them
   unclickable. The basemap is Natural Earth 110m and turns into a flat wash
   long before this limit, but by then you are reading pins, not coastlines. */
var MAX_ZOOM = 4000;
var DRAG_SLOP = 4;       /* px of movement below which a drag counts as a click */

/* ═══════════════════════════════════════════════════════════════════════
   MARKED SETUP — figures with captions, external links in a new tab
   ═══════════════════════════════════════════════════════════════════════ */
marked.use({
  gfm: true,
  breaks: false,
  renderer: {
    image: function (href, title, alt) {
      href = href || ''; title = title || ''; alt = alt || '';
      var html = '<figure><img src="' + href + '"' +
        (alt ? ' alt="' + alt + '"' : '') +
        (title ? ' title="' + title + '"' : '') +
        ' loading="lazy">';
      if (alt) html += '<figcaption>' + alt + '</figcaption>';
      return html + '</figure>';
    },
    link: function (href, title, text) {
      href = href || '#'; title = title || ''; text = text || href;
      var external = /^https?:/.test(href);
      return '<a href="' + href + '"' +
        (title ? ' title="' + title + '"' : '') +
        (external ? ' target="_blank" rel="noopener noreferrer"' : '') +
        '>' + text + '</a>';
    }
  }
});

/* ═══════════════════════════════════════════════════════════════════════
   HELPERS
   ═══════════════════════════════════════════════════════════════════════ */
function $id(id) { return document.getElementById(id); }

function escapeHtml(str) {
  return String(str == null ? '' : str)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

/* Not every trip is pinned to a day. A date may be a year, a year and month, or
   a full date, and each is shown at the precision it was given rather than being
   padded out to a day nobody recorded. */
function formatDate(str) {
  if (!str) return '';
  var m = String(str).match(/^(\d{4})(?:-(\d{2}))?(?:-(\d{2}))?$/);
  if (!m) return str;
  var year = m[1], month = m[2], day = m[3];
  if (!month) return year;
  var d = new Date(year + '-' + month + '-' + (day || '01') + 'T00:00:00');
  if (isNaN(d)) return str;
  return d.toLocaleDateString('en-US', day
    ? { year: 'numeric', month: 'long', day: 'numeric' }
    : { year: 'numeric', month: 'long' });
}

function stripFrontMatter(raw) {
  var m = raw.match(/^---\s*\n([\s\S]*?)\n---\s*\n?/);
  return m ? raw.slice(m[0].length) : raw;
}

function isAbsoluteUrl(url) { return /^(https?:|data:|mailto:|#|\/)/i.test(url); }

function rewriteAssetPaths(markdown, basePath) {
  return markdown.replace(/(!?\[[^\]]*\])\(([^)]+)\)/g, function (full, label, urlPart) {
    var trimmed = urlPart.trim();
    var spaceIdx = trimmed.search(/\s+["']/);
    var rawUrl = spaceIdx >= 0 ? trimmed.slice(0, spaceIdx) : trimmed;
    var suffix = spaceIdx >= 0 ? trimmed.slice(spaceIdx) : '';
    if (isAbsoluteUrl(rawUrl)) return full;
    return label + '(' + basePath + rawUrl + suffix + ')';
  });
}

function clamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }

/* ═══════════════════════════════════════════════════════════════════════
   STATE
   ═══════════════════════════════════════════════════════════════════════ */
var TRIPS = [], PLACES = [], PINS = [];
var bodyCache = {};
var svg = null;
var baseView = null;     /* the viewBox the SVG was generated with */
var view = null;         /* what we are showing now */

function tripBySlug(slug) {
  for (var i = 0; i < TRIPS.length; i++) if (TRIPS[i].slug === slug) return TRIPS[i];
  return null;
}
function placeBySlug(slug) {
  for (var i = 0; i < PLACES.length; i++) if (PLACES[i].slug === slug) return PLACES[i];
  return null;
}

/* ═══════════════════════════════════════════════════════════════════════
   ZOOM AND PAN
   The whole thing is one SVG viewBox. No library, no tiles.
   ═══════════════════════════════════════════════════════════════════════ */
function zoomFactor() { return baseView.w / view.w; }

function applyView() {
  svg.setAttribute('viewBox', view.x + ' ' + view.y + ' ' + view.w + ' ' + view.h);

  /* Counter-scale the pins so they keep their size on screen. Strokes use
     vector-effect="non-scaling-stroke", so only the shapes need this. */
  var k = view.w / baseView.w;
  var pins = svg.querySelectorAll('.pin');
  for (var i = 0; i < pins.length; i++) {
    var px = pins[i].getAttribute('data-x'), py = pins[i].getAttribute('data-y');
    pins[i].setAttribute('transform', 'translate(' + px + ' ' + py + ') scale(' + k + ')');
  }

  var z = zoomFactor();
  var holder = $id('map');
  holder.classList.toggle('is-zoomed', z > 1.02);
  /* At base zoom let a finger scroll the page past the map; once zoomed in the
     map takes the gesture instead. */
  holder.style.touchAction = z > 1.02 ? 'none' : 'pan-y';
  $id('zoom-out').disabled = z <= 1.001;
  $id('zoom-reset').disabled = z <= 1.001;
  $id('zoom-in').disabled = z >= MAX_ZOOM - 0.001;
}

function setView(x, y, w, h) {
  /* Never zoom out past the whole world, and never past MAX_ZOOM in. */
  var minW = baseView.w / MAX_ZOOM;
  w = clamp(w, minW, baseView.w);
  h = w * (baseView.h / baseView.w);
  /* Keep the visible window inside the map. */
  x = clamp(x, baseView.x, baseView.x + baseView.w - w);
  y = clamp(y, baseView.y, baseView.y + baseView.h - h);
  view = { x: x, y: y, w: w, h: h };
  applyView();
}

function zoomBy(factor, cx, cy) {
  /* cx, cy are the fixed point in SVG user units — zoom about the cursor. */
  if (cx == null) { cx = view.x + view.w / 2; cy = view.y + view.h / 2; }
  var newW = clamp(view.w / factor, baseView.w / MAX_ZOOM, baseView.w);
  var k = newW / view.w;
  setView(cx - (cx - view.x) * k, cy - (cy - view.y) * k, newW, 0);
}

function resetView() { setView(baseView.x, baseView.y, baseView.w, baseView.h); }

/** Screen point -> SVG user units. */
function toSvg(clientX, clientY) {
  var r = svg.getBoundingClientRect();
  return {
    x: view.x + (clientX - r.left) / r.width * view.w,
    y: view.y + (clientY - r.top) / r.height * view.h
  };
}

function zoomToPins(list) {
  if (!list.length) return;
  var xs = list.map(function (p) { return projectX(p.lon); });
  var ys = list.map(function (p) { return projectY(p.lat); });
  var minX = Math.min.apply(null, xs), maxX = Math.max.apply(null, xs);
  var minY = Math.min.apply(null, ys), maxY = Math.max.apply(null, ys);
  var pad = Math.max((maxX - minX) * 0.6, (maxY - minY) * 0.6, 28);
  var w = Math.max((maxX - minX) + pad * 2, ((maxY - minY) + pad * 2) * (baseView.w / baseView.h));
  setView((minX + maxX) / 2 - w / 2, (minY + maxY) / 2 - (w * baseView.h / baseView.w) / 2, w, 0);
}

function wirePanZoom() {
  var pointers = {};        /* active pointers, for pinch */
  var dragFrom = null;      /* {x, y, view} in SVG units at drag start */
  var moved = 0;
  var pinchStart = null;

  function pointerList() {
    var out = []; for (var k in pointers) out.push(pointers[k]); return out;
  }

  svg.addEventListener('pointerdown', function (e) {
    pointers[e.pointerId] = { x: e.clientX, y: e.clientY };
    var list = pointerList();
    if (list.length === 1) {
      moved = 0;
      dragFrom = { client: { x: e.clientX, y: e.clientY }, view: { x: view.x, y: view.y } };
      svg.setPointerCapture(e.pointerId);
    } else if (list.length === 2) {
      dragFrom = null;
      pinchStart = {
        dist: Math.hypot(list[0].x - list[1].x, list[0].y - list[1].y),
        w: view.w,
        mid: toSvg((list[0].x + list[1].x) / 2, (list[0].y + list[1].y) / 2)
      };
    }
  });

  svg.addEventListener('pointermove', function (e) {
    if (!pointers[e.pointerId]) return;
    pointers[e.pointerId] = { x: e.clientX, y: e.clientY };
    var list = pointerList();

    if (list.length === 2 && pinchStart) {
      var dist = Math.hypot(list[0].x - list[1].x, list[0].y - list[1].y);
      if (pinchStart.dist > 0) {
        var newW = clamp(pinchStart.w * (pinchStart.dist / dist),
                         baseView.w / MAX_ZOOM, baseView.w);
        var k = newW / view.w;
        setView(pinchStart.mid.x - (pinchStart.mid.x - view.x) * k,
                pinchStart.mid.y - (pinchStart.mid.y - view.y) * k, newW, 0);
      }
      e.preventDefault();
      return;
    }

    if (!dragFrom) return;
    var dx = e.clientX - dragFrom.client.x, dy = e.clientY - dragFrom.client.y;
    moved = Math.max(moved, Math.abs(dx), Math.abs(dy));
    var r = svg.getBoundingClientRect();
    setView(dragFrom.view.x - dx / r.width * view.w,
            dragFrom.view.y - dy / r.height * view.h, view.w, 0);
    if (moved > DRAG_SLOP) e.preventDefault();
  });

  function release(e) {
    delete pointers[e.pointerId];
    if (pointerList().length < 2) pinchStart = null;
    if (!pointerList().length) dragFrom = null;
  }
  svg.addEventListener('pointerup', release);
  svg.addEventListener('pointercancel', release);

  /* A pin click only counts if the pointer barely moved — otherwise the user
     was panning and happened to start on a pin. */
  svg.wasDragged = function () { return moved > DRAG_SLOP; };

  /* Ctrl/Cmd + wheel zooms. A plain wheel is left alone so the page can still
     be scrolled past the map, which an embedded map should never steal. */
  svg.addEventListener('wheel', function (e) {
    if (!(e.ctrlKey || e.metaKey)) return;
    e.preventDefault();
    var p = toSvg(e.clientX, e.clientY);
    zoomBy(e.deltaY < 0 ? 1.28 : 1 / 1.28, p.x, p.y);
  }, { passive: false });

  svg.addEventListener('dblclick', function (e) {
    var p = toSvg(e.clientX, e.clientY);
    zoomBy(e.shiftKey ? 1 / 1.9 : 1.9, p.x, p.y);
  });

  $id('zoom-in').addEventListener('click', function () { zoomBy(1.7); });
  $id('zoom-out').addEventListener('click', function () { zoomBy(1 / 1.7); });
  $id('zoom-reset').addEventListener('click', resetView);
}

/* ═══════════════════════════════════════════════════════════════════════
   MAP
   ═══════════════════════════════════════════════════════════════════════ */
function pinShape(pin) {
  if (pin.shape === 'recommendation') {
    return '<path class="pin__dot" d="M0 -4.4L4.4 0L0 4.4L-4.4 0Z"/>';
  }
  if (pin.shape === 'haunt') {
    return '<circle class="pin__dot pin__dot--ring" r="' + PIN_R + '"/>';
  }
  return '<circle class="pin__dot" r="' + PIN_R + '"/>';
}

function buildMap(svgText) {
  var holder = $id('map');
  holder.insertAdjacentHTML('afterbegin', svgText);
  svg = holder.querySelector('svg');
  if (!svg) throw new Error('world.svg had no <svg> root');

  var vb = (svg.getAttribute('viewBox') || '').split(/[\s,]+/).map(Number);
  if (vb.length !== 4 || vb.some(isNaN)) throw new Error('world.svg has no usable viewBox');
  baseView = { x: vb[0], y: vb[1], w: vb[2], h: vb[3] };
  view = { x: vb[0], y: vb[1], w: vb[2], h: vb[3] };

  var routeLayer = document.createElementNS(SVG_NS, 'g');
  routeLayer.setAttribute('class', 'routes');
  svg.appendChild(routeLayer);

  var pinLayer = document.createElementNS(SVG_NS, 'g');
  pinLayer.setAttribute('class', 'pins');
  svg.appendChild(pinLayer);

  /* Routes: one dashed line per multi-stop trip, in the order listed. */
  TRIPS.forEach(function (trip) {
    if (!trip.places || trip.places.length < 2) return;
    var d = trip.places.map(function (p, i) {
      return (i ? 'L' : 'M') + projectX(p.lon).toFixed(3) + ' ' + projectY(p.lat).toFixed(3);
    }).join('');
    var route = document.createElementNS(SVG_NS, 'path');
    route.setAttribute('class', 'route');
    route.setAttribute('d', d);
    route.setAttribute('data-trip', trip.slug);
    route.setAttribute('vector-effect', 'non-scaling-stroke');
    routeLayer.appendChild(route);
  });

  /* One pin per location, however many things are attached to it. */
  PINS.forEach(function (pin) {
    var g = document.createElementNS(SVG_NS, 'g');
    var cls = 'pin pin--' + pin.shape + (pin.recommended ? ' is-recommended' : '');
    g.setAttribute('class', cls);
    g.setAttribute('data-pin', pin.id);
    /* 4 decimals is ~4m. At 2 decimals (~400m) two restaurants on the same
       road rounded to the same point and one became unclickable. */
    g.setAttribute('data-x', projectX(pin.lon).toFixed(4));
    g.setAttribute('data-y', projectY(pin.lat).toFixed(4));
    g.setAttribute('tabindex', '0');
    g.setAttribute('role', 'button');
    g.setAttribute('aria-label', pinLabel(pin));
    pin.items.forEach(function (it) {
      if (it.type === 'trip') g.setAttribute('data-trip-' + it.slug, '1');
    });

    /* Small dot, large invisible hit area — the pin can be tiny and still
       be comfortable to tap. */
    g.innerHTML = '<circle class="pin__hit" r="' + HIT_R + '"/>' + pinShape(pin);

    g.addEventListener('click', function () {
      if (svg.wasDragged && svg.wasDragged()) return;
      choosePin(pin);
    });
    g.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); choosePin(pin); }
    });
    g.addEventListener('mouseenter', function () { setCaption(pin); });
    g.addEventListener('focus', function () { setCaption(pin); });
    g.addEventListener('mouseleave', clearCaption);
    g.addEventListener('blur', clearCaption);

    pinLayer.appendChild(g);
  });

  applyView();
  wirePanZoom();
}

function pinLabel(pin) {
  var n = pin.items.length;
  return pin.name + (n > 1 ? ' — ' + n + ' entries' : '');
}

function setCaption(pin) {
  var bits = [];
  if (pin.visits) bits.push(pin.visits + (pin.visits === 1 ? ' trip' : ' trips'));
  pin.items.forEach(function (it) {
    if (it.type === 'place') bits.push(it.kind === 'recommendation' ? 'recommended' : 'a haunt');
  });
  $id('map-caption').innerHTML =
    '<strong>' + escapeHtml(pin.name) + '</strong>' +
    (bits.length ? '<span>' + escapeHtml(bits.join(' · ')) + '</span>' : '');
}

function clearCaption() {
  $id('map-caption').innerHTML =
    '<span class="map-hint">Hover a pin for the place, click it to read. ' +
    'Drag to pan, ⌘/Ctrl + scroll or the buttons to zoom.</span>';
}

function highlightMap(slug) {
  var pins = svg ? svg.querySelectorAll('.pin') : [];
  for (var i = 0; i < pins.length; i++) {
    var mine = slug ? pins[i].hasAttribute('data-trip-' + slug) : false;
    pins[i].classList.toggle('is-active', !!slug && mine);
    pins[i].classList.toggle('is-dimmed', !!slug && !mine);
  }
  var routes = svg ? svg.querySelectorAll('.route') : [];
  for (var j = 0; j < routes.length; j++) {
    var r = routes[j].getAttribute('data-trip') === slug;
    routes[j].classList.toggle('is-active', !!slug && r);
    routes[j].classList.toggle('is-dimmed', !!slug && !r);
  }
}

/* ═══════════════════════════════════════════════════════════════════════
   LISTS
   ═══════════════════════════════════════════════════════════════════════ */
function cardHtml(kind, slug, title, meta, summary, cover, coverDir) {
  var img = cover
    ? '<img class="trip-card__img" src="' + coverDir + cover + '" alt="" loading="lazy">'
    : '<span class="trip-card__img trip-card__img--none" aria-hidden="true"></span>';
  return '<button class="trip-card" data-kind="' + kind + '" data-slug="' + escapeHtml(slug) + '">' +
    img +
    '<span class="trip-card__body">' +
      '<span class="trip-card__title">' + escapeHtml(title) + '</span>' +
      '<span class="trip-card__meta">' + meta + '</span>' +
      '<span class="trip-card__summary">' + escapeHtml(summary || '') + '</span>' +
    '</span>' +
  '</button>';
}

function renderLists() {
  var tripList = $id('trip-list');
  if (!TRIPS.length) {
    tripList.innerHTML = '<p class="empty-note">No trips yet. Add one under ' +
      '<code>trips/</code> and run <code>python3 tools/build_travel.py</code>.</p>';
  } else {
    tripList.innerHTML = TRIPS.map(function (t) {
      var n = (t.places || []).length;
      var meta =
        (t.date ? '<span><i class="far fa-calendar-alt"></i> ' + formatDate(t.date) + '</span>' : '') +
        (n ? '<span><i class="fas fa-map-marker-alt"></i> ' + n + (n === 1 ? ' place' : ' places') + '</span>' : '');
      return cardHtml('trip', t.slug, t.title, meta, t.summary, t.cover,
                      'trips/' + encodeURIComponent(t.slug) + '/');
    }).join('');
  }

  var placeList = $id('place-list');
  var section = $id('place-section');
  if (!PLACES.length) {
    section.style.display = 'none';
  } else {
    section.style.display = '';
    placeList.innerHTML = PLACES.map(function (p) {
      var meta = '<span class="kind-chip kind-chip--' + p.kind + '">' +
        (p.kind === 'recommendation' ? 'Recommended' : 'Haunt') + '</span>';
      return cardHtml('place', p.slug, p.name, meta, p.summary, p.cover,
                      'places/' + encodeURIComponent(p.slug) + '/');
    }).join('');
  }

  document.querySelectorAll('.trip-card').forEach(function (card) {
    card.addEventListener('click', function () {
      open(card.getAttribute('data-kind'), card.getAttribute('data-slug'), true);
    });
  });
}

/* ═══════════════════════════════════════════════════════════════════════
   CHOOSER — a pin can carry several things
   ═══════════════════════════════════════════════════════════════════════ */
function choosePin(pin) {
  if (pin.items.length === 1) {
    var only = pin.items[0];
    open(only.type, only.slug, true);
    return;
  }
  var panel = $id('trip-panel');
  panel.classList.add('is-open');
  panel.innerHTML =
    '<div class="chooser">' +
      '<button class="close-trip" type="button" id="close-trip">Close ✕</button>' +
      '<h2>' + escapeHtml(pin.name) + '</h2>' +
      '<p class="chooser__note">' + pin.items.length + ' entries at this place.</p>' +
      '<ul class="chooser__list">' + pin.items.map(function (it) {
        var label = it.type === 'trip'
          ? '<i class="far fa-calendar-alt"></i> ' + escapeHtml(it.title) +
            (it.date ? ' <span class="chooser__date">' + formatDate(it.date) + '</span>' : '')
          : '<i class="fas fa-' + (it.kind === 'recommendation' ? 'star' : 'home') + '"></i> ' +
            escapeHtml(it.title) +
            ' <span class="chooser__date">' +
            (it.kind === 'recommendation' ? 'recommended' : 'haunt') + '</span>';
        return '<li><button type="button" data-kind="' + it.type + '" data-slug="' +
          escapeHtml(it.slug) + '">' + label + '</button></li>';
      }).join('') + '</ul>' +
    '</div>';

  $id('close-trip').addEventListener('click', function () { closePanel(true); });
  panel.querySelectorAll('.chooser__list button').forEach(function (b) {
    b.addEventListener('click', function () {
      open(b.getAttribute('data-kind'), b.getAttribute('data-slug'), true);
    });
  });
  panel.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
}

/* ═══════════════════════════════════════════════════════════════════════
   PANEL
   ═══════════════════════════════════════════════════════════════════════ */
async function fetchBody(dir, slug) {
  var key = dir + '/' + slug;
  if (bodyCache[key] !== undefined) return bodyCache[key];
  var base = dir + '/' + encodeURIComponent(slug) + '/';
  var res = await fetch(base + 'index.md');
  if (!res.ok) throw new Error('HTTP ' + res.status);
  var raw = await res.text();
  var html = marked.parse(rewriteAssetPaths(stripFrontMatter(raw), dir + '/' + slug + '/'));
  bodyCache[key] = html;
  return html;
}

function galleryHtml(photos, dir, slug) {
  if (!photos || !photos.length) return '';
  var base = dir + '/' + encodeURIComponent(slug) + '/';
  return '<div class="gallery">' + photos.map(function (photo) {
    return '<figure><img src="' + base + photo.src + '" alt="' +
      escapeHtml(photo.caption) + '" loading="lazy">' +
      (photo.caption ? '<figcaption>' + escapeHtml(photo.caption) + '</figcaption>' : '') +
      '</figure>';
  }).join('') + '</div>';
}

async function open(kind, slug, push) {
  var entry = kind === 'trip' ? tripBySlug(slug) : placeBySlug(slug);
  if (!entry) { closePanel(push); return; }

  var dir = kind === 'trip' ? 'trips' : 'places';
  var title = kind === 'trip' ? entry.title : entry.name;

  highlightMap(kind === 'trip' ? slug : null);
  if (kind === 'trip') {
    zoomToPins(entry.places || []);
  } else {
    zoomToPins([{ lat: entry.lat, lon: entry.lon }]);
  }
  clearCaption();
  $id('nav-breadcrumb').textContent = title;
  document.title = title + ' | Travel | Sagalpreet Singh';

  if (push) {
    var q = '?' + kind + '=' + encodeURIComponent(slug);
    if (location.search !== q) history.pushState({ kind: kind, slug: slug }, '', 'travel.html' + q);
  }

  var meta = kind === 'trip'
    ? (entry.date ? '<span><i class="far fa-calendar-alt"></i> ' + formatDate(entry.date) + '</span>' : '') +
      ((entry.places || []).length
        ? '<span class="memoir__places">' + entry.places.map(function (p) {
            return '<span class="memoir__place">' + escapeHtml(p.name) + '</span>';
          }).join('') + '</span>'
        : '')
    : '<span class="kind-chip kind-chip--' + entry.kind + '">' +
      (entry.kind === 'recommendation' ? 'Recommended' : 'Haunt') + '</span>';

  var panel = $id('trip-panel');
  panel.classList.add('is-open');
  panel.innerHTML =
    '<article class="memoir">' +
      '<div class="memoir__head">' +
        '<button class="close-trip" type="button" id="close-trip">Close ✕</button>' +
        '<h2>' + escapeHtml(title) + '</h2>' +
        '<div class="memoir__meta">' + meta + '</div>' +
      '</div>' +
      '<div class="prose" id="memoir-body"><p class="empty-note">Loading…</p></div>' +
      galleryHtml(entry.photos, dir, slug) +
    '</article>';

  $id('close-trip').addEventListener('click', function () { closePanel(true); });

  try {
    $id('memoir-body').innerHTML = await fetchBody(dir, slug);
  } catch (err) {
    $id('memoir-body').innerHTML =
      '<p class="empty-note">Could not load this one (' + escapeHtml(err.message) + ').</p>';
  }
  panel.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
}

function closePanel(push) {
  highlightMap(null);
  clearCaption();
  var panel = $id('trip-panel');
  panel.classList.remove('is-open');
  panel.innerHTML = '';
  $id('nav-breadcrumb').textContent = 'Travel';
  document.title = 'Travel | Sagalpreet Singh';
  if (push) history.pushState({}, '', 'travel.html');
}

/* ═══════════════════════════════════════════════════════════════════════
   ROUTING + BOOT
   ═══════════════════════════════════════════════════════════════════════ */
function route() {
  var q = new URLSearchParams(location.search);
  var trip = q.get('trip'), place = q.get('place');
  if (trip && tripBySlug(trip)) open('trip', trip, false);
  else if (place && placeBySlug(place)) open('place', place, false);
  else { closePanel(false); resetView(); }
}

function showError(msg) {
  $id('loading-indicator').style.display = 'none';
  $id('content').style.display = 'none';
  var box = $id('error-container');
  box.style.display = 'block';
  $id('error-message').textContent = msg;
}

async function init() {
  try {
    var results = await Promise.all([
      fetch('trips/index.json').then(function (r) {
        if (!r.ok) throw new Error('trips/index.json — HTTP ' + r.status);
        return r.json();
      }),
      fetch('assets/world.svg').then(function (r) {
        if (!r.ok) throw new Error('assets/world.svg — HTTP ' + r.status);
        return r.text();
      })
    ]);

    var data = results[0] || {};
    TRIPS = data.trips || [];
    PLACES = data.places || [];
    PINS = data.pins || [];

    $id('loading-indicator').style.display = 'none';
    $id('content').style.display = 'block';

    buildMap(results[1]);
    renderLists();
    clearCaption();

    route();
    window.addEventListener('popstate', route);
  } catch (err) {
    showError('Could not load the map: ' + err.message +
      '. If you are opening this from the filesystem, serve it over HTTP instead.');
  }
}

document.addEventListener('DOMContentLoaded', init);
